/*
  The common case types (models/hospital-subset/subset.json): 29 specs: Coronary bypass 11, Renal failure 7, Sepsis 11. Each spec as it stands at the end of the stay,
  each spec node dated by its first appearance in the data (MIMIC's own date-shifted times).
  Generated by models/hospital-subset/subset.py; a summary is in cases.json beside this script. Run after the master
  care tree (models/hospital). Replaces earlier runs of these specs (by name; @Reset = 1). Set @Commit = 0 for a dry run.
*/
USE [Results];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit         bit              = 1;   -- 0 = dry run
DECLARE @Reset          bit              = 1;   -- 1 = remove earlier runs of these specs first
DECLARE @OrganisationId uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @ResultId       int              = 45;
DECLARE @CreatedBy      uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';

IF ISNULL(COLUMNPROPERTY(OBJECT_ID('dbo.SpecNodes'), 'Id', 'IsIdentity'), 0) <> 1
BEGIN
    RAISERROR('SpecNodes.Id is not an identity column: nothing written.', 16, 1);
    RETURN;
END

DECLARE @specs TABLE (SpecName nvarchar(400) PRIMARY KEY, Description nvarchar(1000), Started datetime2,
                      SpecId uniqueidentifier NULL);
DECLARE @nodes TABLE (SpecName nvarchar(400), Path nvarchar(2000), Depth int, Added datetime2, ResultNodeId int NULL,
                      ParentResultNodeId int NULL, Name nvarchar(400) NULL);

-- Result nodes of the care tree by path.
DECLARE @paths TABLE (Id int PRIMARY KEY, ParentId int NULL, Name nvarchar(400), Path nvarchar(2000));
;WITH t AS (
    SELECT Id, ParentResultNodeId, Name, CAST(Name AS nvarchar(2000)) AS Path FROM dbo.ResultNodes
    WHERE ParentResultNodeId IS NULL AND Name = N'Patient' AND ResultId = @ResultId AND OrganisationId = @OrganisationId
    UNION ALL
    SELECT c.Id, c.ParentResultNodeId, c.Name, CAST(t.Path + N' > ' + c.Name AS nvarchar(2000))
    FROM dbo.ResultNodes c JOIN t ON c.ParentResultNodeId = t.Id
)
UPDATE n SET ResultNodeId = p.Id, ParentResultNodeId = p.ParentId, Name = p.Name
FROM @nodes n JOIN @paths p ON p.Path COLLATE DATABASE_DEFAULT = n.Path COLLATE DATABASE_DEFAULT;

IF EXISTS (SELECT 1 FROM @nodes WHERE ResultNodeId IS NULL)
BEGIN
    SELECT DISTINCT TOP (50) Path, 'result node not found (run care_tree.sql)' AS Problem FROM @nodes WHERE ResultNodeId IS NULL;
    RAISERROR('Some result nodes could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

-- Remove earlier runs of these specs (their values, nodes, then the specs).
DECLARE @specsRemoved int = 0;
IF @Reset = 1
BEGIN
    DECLARE @old TABLE (Id uniqueidentifier PRIMARY KEY);
    WHERE s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
    DELETE v FROM dbo.SpecNodePropertyValues v JOIN dbo.SpecNodes n ON n.Id = v.SpecNodeId JOIN @old o ON o.Id = n.SpecId;
    UPDATE n SET ParentSpecNodeId = NULL FROM dbo.SpecNodes n JOIN @old o ON o.Id = n.SpecId;
    DELETE n FROM dbo.SpecNodes n JOIN @old o ON o.Id = n.SpecId;
    DELETE s FROM dbo.Specs s JOIN @old o ON o.Id = s.Id;
    SET @specsRemoved = @@ROWCOUNT;
END

-- The specs.
                       ModificationDate, IsTemplate, TemplateId, ClientId, ContractId, OrganisationId, CreatedBy, ModifiedBy,
                       TargetAtlasId, SourceOrganisationId, TargetDate, AssignmentId)
SELECT NEWID(), @ResultId, 11, 1, x.SpecName, x.Description, NULL, NULL, x.Started,
       NULL, 0, NULL, NULL, NULL, @OrganisationId, @CreatedBy, NULL,
       '3B30813B-994F-4BB1-A70F-9763E2B61154', NULL, NULL, NULL
FROM @specs x
WHERE NOT EXISTS (SELECT 1 FROM dbo.Specs s WHERE s.Name COLLATE DATABASE_DEFAULT = x.SpecName COLLATE DATABASE_DEFAULT
                  AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId);
DECLARE @specsAdded int = @@ROWCOUNT;
UPDATE x SET SpecId = s.Id FROM @specs x
JOIN dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = x.SpecName COLLATE DATABASE_DEFAULT
                AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;

-- Spec nodes, depth by depth, each under its parent's spec node.
DECLARE @depth int = 0, @nodesAdded int = 0;
WHILE @depth <= (SELECT ISNULL(MAX(Depth), -1) FROM @nodes)
BEGIN
    SELECT n.Name, n.ResultNodeId, ps.Id, n.Added, NULL, x.SpecId, @CreatedBy, NULL
    FROM @nodes n
    JOIN @specs x ON x.SpecName = n.SpecName
    LEFT JOIN dbo.SpecNodes ps ON ps.SpecId = x.SpecId AND ps.ResultNodeId = n.ParentResultNodeId
    WHERE n.Depth = @depth
      AND NOT EXISTS (SELECT 1 FROM dbo.SpecNodes y WHERE y.SpecId = x.SpecId AND y.ResultNodeId = n.ResultNodeId);
    SET @nodesAdded += @@ROWCOUNT;
    SET @depth += 1;
END

SELECT @specsRemoved AS SpecsRemoved, @specsAdded AS SpecsAdded, @nodesAdded AS SpecNodesAdded,
       (SELECT COUNT(*) FROM @specs) AS SpecsExpected, (SELECT COUNT(*) FROM @nodes) AS SpecNodesExpected;

IF @nodesAdded <> (SELECT COUNT(*) FROM @nodes) AND @Reset = 1
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR('Spec node count mismatch: rolled back.', 16, 1);
END
ELSE IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE                BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
